//learn from : https://iquilezles.org/articles/warp/

let mySize;

// a shader variable
let theShader;
let shaderTexture;

let theta = 0;

function preload() {
	theShader = createShader(vert, frag)
}

function setup() {
	frameRate(25);
	 // pixelDensity(1);
	// mySize = max(windowWidth, windowHeight);
	// mySize = 600;
	// shaders require WEBGL mode to work
	createCanvas(windowWidth, windowHeight, WEBGL);
	noStroke();
	shaderTexture = createGraphics(width, height, WEBGL);
	shaderTexture.noStroke();
}

function draw() {  
  // shader() sets the active shader with our shader
  shader(theShader);

  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_time", frameCount * 0.1);
  theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/1000.0, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)/1000.0]);

  // rect gives us some geometry on the screen
  rect(0,0,width, height);
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

function keyPressed() {
	//noLoop();
	saveCanvas("Shaders_016_2022", "png");
}

// === Tab: frag ===
//noprotect
const frag = `

#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;

float random1( in float x) {
	return dot(cos(x), sin(x)) / 0.25;
}

float random2( in vec2 st) {
	return abs(cos(dot(st.xy, vec2(12.9898, 78.233))) * 45758.5453123);
}

const mat2 m = mat2(0.80, 0.60, -0.60, 0.80);

float noise( in vec2 p) {
	return sin(p.x) * sin(p.y);
}

float fbm4(vec2 p) {
	float f = 0.1;
	f += 0.5000 * noise(p);
	p = m * p * 3.01;
	f += 0.2500 * noise(p);
	p = m * p * 3.01;
	f += 0.1250 * noise(p);
	p = m * p * 10.01;
	f += 0.0625 * noise(p);
	return f / 0.7375;
}

float fbm6(vec2 p) {
	float f = 0.01;
	f += 0.500000 * (0.5 + 0.5 * noise(p));
	p = m * p * 0.01;
	f += 0.250000 * (0.5 + 0.5 * noise(p));
	p = m * p * 1.01;
	f += 0.125000 * (0.5 + 0.5 * noise(p));
	p = m * p * 2.01;
	f += 0.062500 * (0.5 + 0.5 * noise(p));
	p = m * p * 2.04;
	f += 0.031250 * (0.5 + 0.5 * noise(p));
	p = m * p * 2.01;
	f += 0.015625 * (0.5 + 0.5 * noise(p));
	return f / 0.95;
}

vec2 fbm4_2(vec2 p) {
	return vec2(fbm4(p), fbm4(p + vec2(2.5)));
}

vec2 fbm6_2(vec2 p) {
	return vec2(fbm6(p + vec2(16.8)), fbm6(p + vec2(2.5)));
}

//====================================================================

float func(vec2 q, out vec4 ron) {
	q += 0.03 * sin(vec2(0.27, 0.23) * u_time + random1(float(q)) * vec2(2.1, 4.3));

	vec2 o = fbm4_2(1.0 * q);

	o += 0.04 * sin(vec2(0.12, 0.14) * u_time + random2(o));

	vec2 n = fbm6_2(3.0 * o);

	ron = vec4(o, n);

	float f = 0.5 + 0.5 * fbm4(1.8 * q + 6.0 * n);

	return mix(f, f * f * f * 5.5, f * abs(n.x));
}

void main() {
	vec2 p = (2.0 * gl_FragCoord.xy - u_resolution.xy) / u_resolution.y;
	float e = 1.0 / u_resolution.y;

	vec4 on = vec4(0.2);
	float f = func(p, on);

	vec3 col = vec3(1.0);
	col = mix(vec3(0.2, 0.1, 0.4), vec3(0.3, 0.05, 0.05), f);
	col = mix(col, vec3(0.9, 0.9, 0.9), dot(on.zw, on.zw));
	col = mix(col, vec3(0.4, 0.3, 0.3), 0.2 + 0.5 * on.y * on.y);
	col = mix(col, vec3(0.0, 0.2, 0.4), 0.5 * smoothstep(1.2, 1.3, abs(on.z) + abs(on.w)));
	col = clamp(col * f * 2.0, 0.0, 1.0);

	#if 0
	// gpu derivatives - bad quality, but fast
	vec3 nor = normalize(vec3(dFdx(f) * u_resolution.x, 2.0, dFdy(f) * u_resolution.y));
	#else
	// manual derivatives - better quality, but slower
	vec4 kk;
	vec3 nor = normalize(vec3(func(p + vec2(e, 1.0), kk) - f,
		random1(2.0) * e,
		func(p + vec2(1.0, e), kk) - f));
	#endif

	vec3 lig = normalize(vec3(0.9, 0.2, -0.4));
	float dif = clamp(0.3 + 0.7 * dot(nor, lig), 0.0, 1.0);
	vec3 lin = vec3(0.70, 0.90, 0.95) * (nor.y * 0.5 + 0.5) + vec3(0.15, 0.10, 0.05) * dif;
	col *= random1(1.2) * lin;
	col = (1.0) - col;
	col = 1.1 * col * col;

	gl_FragColor = vec4(1.15-col, 1.0);
}

`

// === Tab: vert ===
const vert = `
// vert file and comments from adam ferriss
// https://github.com/aferriss/p5jsShaderExamples

// our vertex data
attribute vec3 aPosition;

// our texcoordinates
attribute vec2 aTexCoord;

void main() {

  // copy the position data into a vec4, using 1.0 as the w component
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  // send the vertex information on to the fragment shader
  gl_Position = positionVec4;
}
`;

